import manifest from './generated/images.json'

/** Responsive WebP variants generated by `npm run images` (scripts/optimize-images.mjs). */
export interface ImageEntry {
  width: number
  height: number
  variants: { width: number; src: string }[]
}

const images: Record<string, ImageEntry> = manifest

export function image(name: string): ImageEntry {
  const entry = images[name]
  if (!entry) throw new Error(`Unknown image "${name}". Add it to IMAGES in scripts/optimize-images.mjs.`)
  return entry
}

export const srcset = (entry: ImageEntry) => entry.variants.map(v => `${v.src} ${v.width}w`).join(', ')

/** The smallest variant at least `minWidth` wide (or the largest), for CSS backgrounds and fallbacks. */
export function imageUrl(name: string, minWidth = Infinity) {
  const { variants } = image(name)
  return (variants.find(v => v.width >= minWidth) ?? variants.at(-1)!).src
}

/** A page's above-the-fold image. `sizes` must match the `<ResponsiveImage>` that renders it. */
export interface HeroImage {
  image: string
  sizes?: string
}

/** Full-bleed heroes are rendered at the viewport width. */
export const HERO_SIZES = '100vw'

/** The publications figure crops a landscape photo to 4:5, so it needs the full-width file on desktop. */
export const PUBLICATIONS_HERO_SIZES = '(max-width: 820px) 100vw, 64rem'

/** Preload tag for a page's hero, written into prerendered HTML so the request starts before CSS and JS. */
export function heroPreload({ image: name, sizes = HERO_SIZES }: HeroImage) {
  return `<link rel="preload" as="image" fetchpriority="high" imagesrcset="${srcset(image(name))}" imagesizes="${sizes}">`
}
